import{_ as s,o as a,c as t,ag as i}from"./chunks/framework.B3TlH8dL.js";const c=JSON.parse('{"title":"Backup and restore","description":"","frontmatter":{},"headers":[],"relativePath":"operations/backup-restore.md","filePath":"operations/backup-restore.md","lastUpdated":1793170150000}'),n={name:"operations/backup-restore.md"};function o(r,e,h,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="backup-and-restore" tabindex="-1">Backup and restore <a class="header-anchor" href="#backup-and-restore" aria-label="Permalink to &quot;Backup and restore&quot;">​</a></h1><p>A backup is three things, taken at the same point in time:</p><ol><li><strong>The database</strong> (<code>pg_dump</code>, <code>mysqldump --single-transaction</code>, or the SQLite file with <code>sqlite3 database.sqlite &quot;.backup backup.sqlite&quot;</code>).</li><li><strong>The storage</strong> (the <code>storage.root</code> folder, or the bucket: turn on bucket versioning so a snapshot can be read as of a time).</li><li><strong>The keys</strong>: <code>APP_KEY</code> and every key in <code>APP_PREVIOUS_KEYS</code> at the time (during an unfinished <a href="./app-key.html">rotation</a>, the database holds values under several keys), kept apart from both. Without them, saved secrets (the SMTP password, other settings secrets) and your <a href="./../digging-deeper/encryption.html">encrypted columns</a> cannot be decrypted, and sessions and links stop working.</li></ol><h2 id="taking-a-consistent-backup" tabindex="-1">Taking a consistent backup <a class="header-anchor" href="#taking-a-consistent-backup" aria-label="Permalink to &quot;Taking a consistent backup&quot;">​</a></h2><p>Files referenced by the database may be deleted while a live backup runs (pruning, media removal). Either:</p><ul><li>stop the web and worker processes, dump the database, copy the storage, start again; or</li><li>dump the database, and restore the storage <em>as of the dump&#39;s time</em> from the bucket&#39;s versions (versioning keeps deleted objects for a while).</li></ul><h2 id="keys-and-rotated-backups" tabindex="-1">Keys and rotated backups <a class="header-anchor" href="#keys-and-rotated-backups" aria-label="Permalink to &quot;Keys and rotated backups&quot;">​</a></h2><p>Encrypted values open with <code>APP_KEY</code> or with a key in <code>APP_PREVIOUS_KEYS</code>. To restore a backup taken before a <a href="./app-key.html">key rotation</a>, restore with the whole set of keys the backup needs: either the backup&#39;s keys as they were (<code>APP_KEY</code> and <code>APP_PREVIOUS_KEYS</code>), or keep the current key as <code>APP_KEY</code> and list every key of the backup in <code>APP_PREVIOUS_KEYS</code> (never the current key itself: boot fails). Then run <code>rustcms key:reencrypt</code>, with that same environment, to move the restored values to the current key. A value no key you hold opens cannot be recovered: <code>key:reencrypt</code> lists it as unreadable (check first that the command ran with every key you have), and it must be set again.</p><h2 id="restoring" tabindex="-1">Restoring <a class="header-anchor" href="#restoring" aria-label="Permalink to &quot;Restoring&quot;">​</a></h2><ol><li><p>Stop every web and worker process.</p></li><li><p>Restore the database and the storage of the same point in time, with the keys that sealed them (see above).</p></li><li><p>Before opening, end what the backup brought back: every session and JWT sign-in (a sign-in revoked after the backup would work again), links of resets and invitations, and mail jobs that were waiting:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> sessions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> jwt_refresh_tokens;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> jwt_families;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_tokens;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DELETE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> jobs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> kind </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;auth.password_reset&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;auth.invitation&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mail.send&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Revoke API tokens too if the backup may hold some that were revoked since:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> personal_access_tokens </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> revoked_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CURRENT_TIMESTAMP </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> revoked_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li><li><p><strong>Check every other job the backup brought back</strong> before any worker starts (<code>SELECT id, kind, queue, created_at, description FROM jobs</code>): your own jobs, exports, imports and <code>rustcms.schedule.run</code> (a Run now of a task schedule). Any of them may already have run after the backup was taken, and the restored <code>job_receipts</code> predate those runs, so <code>queue::once</code> does not stop them from running again. Delete the jobs whose effects already happened outside the database (a mail, a payment, a call to another service).</p></li><li><p><code>rustcms migrate:status</code>, then <code>rustcms migrate</code> if the code is newer. If migrations show as <code>Newer</code>, the database was written by a newer binary: restore with that binary (or a newer one). <code>rustcms migrate --allow-newer</code> leaves those migrations as they are and runs this version&#39;s pending ones; use it only after checking that every unknown migration only adds tables or nullable columns, so the older code still works with the schema.</p></li><li><p>Start the processes; users sign in again.</p></li></ol><p>A missed schedule slot is skipped, never caught up, so the scheduler tables (<code>schedule_states</code>, <code>schedule_slots</code>, <code>schedule_runs</code>) need nothing special; that does not cover jobs already in the <code>jobs</code> table (step 4).</p><p>Rehearse a restore on a copy: check that files open, that sign-in works, and that <code>rustcms key:reencrypt --dry-run</code>, run with the restored environment, succeeds (every encrypted value opens with the current key).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./app-key.html">Rotating APP_KEY</a></li><li><a href="./retention.html">Data retention</a></li><li><a href="./../digging-deeper/storage.html">File storage</a></li><li><a href="./../reference/database-schema.html">Database schema</a></li></ul>`,14)])])}const u=s(n,[["render",o]]);export{c as __pageData,u as default};
